namespace sv_a88510262abd47f4bd2f5590763849f8.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

public sealed class ShipmentDetails
{
    public required string TrackingNumber { get; init; }
    public required string Status { get; init; }
    public required string Location { get; init; }
    public required DateTimeOffset EstimatedDelivery { get; init; }
    public required IReadOnlyList<StatusUpdate> StatusUpdates { get; init; }
}

public sealed class StatusUpdate
{
    public required string Description { get; init; }
    public required DateTimeOffset Timestamp { get; init; }
}

using sv_a88510262abd47f4bd2f5590763849f8.Client.Services;

namespace sv_a88510262abd47f4bd2f5590763849f8.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new ShipmentDetails
        {
            TrackingNumber = "TRK-001",
            Status = "In Transit",
            Location = "Memphis, TN",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 9, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Timestamp = new DateTimeOffset(2026, 7, 4, 10, 0, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "Arrived at sorting facility", Timestamp = new DateTimeOffset(2026, 7, 5, 6, 30, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "Departed Memphis hub", Timestamp = new DateTimeOffset(2026, 7, 6, 2, 15, 0, TimeSpan.Zero) },
            ]
        },
        ["TRK-002"] = new ShipmentDetails
        {
            TrackingNumber = "TRK-002",
            Status = "Delivered",
            Location = "Seattle, WA",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 5, 12, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Timestamp = new DateTimeOffset(2026, 7, 2, 8, 0, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "In transit", Timestamp = new DateTimeOffset(2026, 7, 3, 14, 0, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "Out for delivery", Timestamp = new DateTimeOffset(2026, 7, 5, 9, 0, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "Delivered - Left at front door", Timestamp = new DateTimeOffset(2026, 7, 5, 11, 42, 0, TimeSpan.Zero) },
            ]
        },
        ["TRK-003"] = new ShipmentDetails
        {
            TrackingNumber = "TRK-003",
            Status = "Processing",
            Location = "Chicago, IL",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 11, 18, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Label created", Timestamp = new DateTimeOffset(2026, 7, 6, 3, 0, 0, TimeSpan.Zero) },
            ]
        },
    };

    public async Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"Shipment with tracking number '{trackingNumber}' not found.");
    }
}

using System.Net.Http.Json;

namespace sv_a88510262abd47f4bd2f5590763849f8.Client.Services;

public sealed class HttpShipmentService : IShipmentService
{
    private readonly HttpClient _http;

    public HttpShipmentService(HttpClient http)
    {
        _http = http;
    }

    public async Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct)
